import presmium_gpu as gpu
SHADER = "@group(0) @binding(0) var<storage, read> a: array<f32>;
@group(0) @binding(1) var<storage, read> b: array<f32>;
@group(0) @binding(2) var<storage, read_write> out: array<f32>;
@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
 if (id.x < arrayLength(&out)) { out[id.x] = a[id.x] + b[id.x]; }
}"
result = await gpu.run(SHADER, buffers={"a":[1,2,3,4],"b":[10,20,30,40],"out":{"size":4}})
print(result)
print("同步桥接可用：", gpu.can_run_sync())

